 bool gesturesForCheck(){sync();fitPitch();auto event=[&](juce::Point<float> pos,juce::ModifierKeys mods,int clicks=1){return juce::MouseEvent(juce::Desktop::getInstance().getMainMouseSource(),pos,mods,1,0,0,0,0,&roll,&roll,juce::Time::getCurrentTime(),pos,juce::Time::getCurrentTime(),clicks,false);};if(view.notes.empty())return false;auto point=bounds(view.notes[0]).getCentre();int id=view.notes[0].id,velocity=view.notes[0].velocity;auto mods=juce::ModifierKeys(juce::ModifierKeys::leftButtonModifier|juce::ModifierKeys::commandModifier|juce::ModifierKeys::shiftModifier);noteDown(event(point,mods));noteDrag(event(point.translated(0,-15),mods));finish();auto n=std::find_if(view.notes.begin(),view.notes.end(),[&](auto n){return n.id==id;});if(n==view.notes.end()||n->velocity!=juce::jmin(127,velocity+15))return false;mutate([&](auto& c){for(auto& note:c.notes)if(note.id==id)note.beat=.13;});n=std::find_if(view.notes.begin(),view.notes.end(),[&](auto n){return n.id==id;});auto moveStart=bounds(*n).getCentre();noteDown(event(moveStart,juce::ModifierKeys::leftButtonModifier));noteDrag(event(moveStart.translated((float)(noteArea().getWidth()/span()*.25),0),juce::ModifierKeys::leftButtonModifier));finish();n=std::find_if(view.notes.begin(),view.notes.end(),[&](auto n){return n.id==id;});if(n==view.notes.end()||std::abs(n->beat-.5)>1e-6)return false;auto count=view.notes.size();doubleClick(event(bounds(*n).getCentre(),juce::ModifierKeys::leftButtonModifier,2));if(view.notes.size()!=count-1)return false;pencilOn=true;auto a=noteArea();auto pos=juce::Point<float>(xAt(1.1),a.getY()+rowHeight()*2.5f);noteDown(event(pos,juce::ModifierKeys::leftButtonModifier));noteDrag(event(pos.translated((float)(a.getWidth()/span()),0),juce::ModifierKeys::leftButtonModifier));finish();if(view.notes.size()<count+2)return false;for(auto n:view.notes)if(selected.count(n.id)&&std::abs(n.beat/grid-std::round(n.beat/grid))>1e-6)return false;return true;}
 bool load(juce::File file){bool ok=p.loadSequence(file);if(ok){selected.clear();zoom=1;offset=0;sync();fitPitch();}if(message)message(ok?"MIDI loaded: "+file.getFileName():"Could not load MIDI (PPQ note clips up to 512 bars).");return ok;}
 bool isInterestedInFileDrag(const juce::StringArray& paths)override{for(auto path:paths)if(SequenceClip::midi(juce::File(path)))return true;return false;}void filesDropped(const juce::StringArray& paths,int,int)override{for(auto path:paths)if(SequenceClip::midi(juce::File(path))){load(juce::File(path));return;}}
 void resized()override{int w=getWidth(),x=0,y=0;auto place=[&](juce::Component& c,int width){if(x+width>w){x=0;y+=31;}c.setBounds(x,y,width,26);x+=width+5;};place(enable,26);place(title,juce::jlimit(110,210,w/4));place(record,108);place(importButton,100);place(saveButton,55);place(saveAs,70);x=0;y+=33;place(pencil,28);place(down,34);place(up,34);place(octDown,38);place(octUp,38);place(quantise,88);place(duplicate,90);place(barsLabel,35);place(bars,40);place(gridBox,65);if(!p.oneShotMode)place(fromSlices,105);if(p.oneShotMode){if(x+168>w){x=0;y+=31;}place(keyLabel,64);place(key,94);}x=0;y+=31;place(swingButton,65);place(swingAmount,140);for(auto& group:swingGroups)place(group,28);int topY=y+34;roll.setBounds(0,topY,w,juce::jmax(110,getHeight()-topY-43));pan.setBounds(64,roll.getBottom()+4,juce::jmax(1,w-64),12);status.setBounds(0,getHeight()-22,w,20);}
 void paint(juce::Graphics& g)override{g.fillAll(palette::bg());}
